input.content:
@font-face {
  font-family: 'Press Start 2P';
  src: url('../assets/fonts/press-start-2p.woff2') format('woff2');
  font-display: swap;
}

@font-face {
  font-family: 'VT323';
  src: url('../assets/fonts/vt323.woff2') format('woff2');
  font-display: swap;
}

:root {
  --ink: #241609;
  --ink-soft: #3a2513;
  --paper: #f2dcaa;
  --paper-2: #e4c68d;
  --paper-3: #fff1cb;
  --gold: #f2c14e;
  --gold-dark: #b9822c;
  --red: #c9503c;
  --red-dark: #8f2f25;
  --green: #6fae4a;
  --green-dark: #3f6e2c;
  --blue: #4b7fae;
  --cream: #fff4d6;
  --shadow: rgba(8, 6, 3, 0.55);
  --font-pixel: 'Press Start 2P', 'Courier New', monospace;
  --font-body: 'VT323', 'Courier New', monospace;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #101a10;
  color: var(--ink);
  font-family: var(--font-body);
  -webkit-font-smoothing: none;
  text-rendering: optimizeSpeed;
  overscroll-behavior: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 3px solid #ffe08a;
  outline-offset: 2px;
}

img {
  -webkit-user-drag: none;
  user-select: none;
}

.hidden {
  display: none !important;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

#game-canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
  z-index: 1;
}

#crt {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background:
    repeating-linear-gradient(
      0deg,
      rgba(0, 0, 0, 0.1) 0px,
      rgba(0, 0, 0, 0.1) 1px,
      transparent 1px,
      transparent 3px
    ),
    radial-gradient(ellipse at 50% 45%, transparent 52%, rgba(6, 10, 6, 0.5) 100%);
  opacity: 0.5;
  mix-blend-mode: multiply;
}

body.crt-off #crt {
  display: none;
}

#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
}

/* ------------------------------------------------------------- top bar */

#topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  min-height: 64px;
  padding: calc(7px + var(--safe-top)) 14px 7px;
  display: flex;
  align-items: center;
  gap: 18px;
  pointer-events: auto;
  background:
    linear-gradient(180deg, rgba(255, 220, 160, 0.09), transparent 40%),
    repeating-linear-gradient(90deg, rgba(0, 0, 0, 0.12) 0 2px, transparent 2px 6px),
    linear-gradient(180deg, #5a3a1e 0%, #3c2511 68%, #2b190a 100%);
  border-bottom: 4px solid #1a1008;
  box-shadow:
    0 0 0 2px #7a4e24,
    0 5px 0 rgba(0, 0, 0, 0.4),
    0 10px 24px rgba(0, 0, 0, 0.35);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-shrink: 0;
}

.brand-logo {
  width: 38px;
  height: 38px;
  image-rendering: pixelated;
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, 0.45));
}

.brand-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.brand-title {
  font-family: var(--font-pixel);
  font-size: 11px;
  letter-spacing: 0.06em;
  color: var(--gold);
  text-shadow:
    2px 2px 0 #1a1008,
    -1px -1px 0 #8a5a1e;
}

.brand-sub {
  font-family: var(--font-pixel);
  font-size: 5px;
  letter-spacing: 0.16em;
  color: #c9a26b;
}

.resources {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 1;
  min-width: 0;
}

.res-chip {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 36px;
  padding: 0 9px 0 6px;
  background: linear-gradient(180deg, #2a1a0d, #1c1108);
  border: 2px solid #8a6336;
  box-shadow:
    inset 0 0 0 1px #0f0904,
    inset 0 2px 0 rgba(255, 218, 150, 0.08),
    0 2px 0 rgba(0, 0, 0, 0.4);
  white-space: nowrap;
}

.res-chip img {
  width: 20px;
  height: 20px;
  image-rendering: pixelated;
  filter: drop-shadow(0 1px 0 #000);
}

.res-val {
  font-family: var(--font-pixel);
  font-size: 10px;
  color: var(--cream);
  letter-spacing: 0.02em;
}

.res-cap {
  font-family: var(--font-pixel);
  font-size: 7px;
  color: #b18a58;
  align-self: flex-end;
  margin-bottom: 6px;
}

.res-chip.full .res-val {
  color: #ff8f75;
}

.res-chip.full {
  animation: chip-pulse 1.2s ease-in-out infinite;
  border-color: #c9503c;
}

.res-chip.res-pop {
  border-color: #4f7f9f;
}

.res-chip.res-idle {
  border-color: #6f8f45;
}

.res-label {
  font-family: var(--font-pixel);
  font-size: 5px;
  color: #9fbf76;
  letter-spacing: 0.08em;
  align-self: flex-end;
  margin-bottom: 7px;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-shrink: 0;
}

.speed-group {
  display: flex;
  gap: 3px;
}

.speed-btn,
.top-btn {
  font-family: var(--font-pixel);
  font-size: 7px;
  letter-spacing: 0.02em;
  color: #e8ce9b;
  background: linear-gradient(180deg, #4c3118, #2b190a);
  border: 2px solid #8a6336;
  box-shadow:
    inset 0 0 0 1px #120b05,
    0 2px 0 #120b05;
  height: 30px;
  padding: 0 7px;
  cursor: pointer;
}

.speed-btn {
  min-width: 29px;
  padding: 0 5px;
}

.speed-btn:hover,
.top-btn:hover {
  background: linear-gradient(180deg, #63401f, #3a2511);
  color: #fff1cb;
}

.speed-btn.active {
  color: #3a2513;
  background: linear-gradient(180deg, #ffd977, #e0a93c);
  border-color: #fff1cb;
  box-shadow:
    inset 0 0 0 1px #8a5a1e,
    0 2px 0 #120b05;
}

.top-btn {
  color: #d8b980;
}

.speed-btn:active,
.top-btn:active {
  transform: translateY(1px);
  box-shadow: inset 0 0 0 1px #120b05;
}

/* ------------------------------------------------------------- panels */

.panel {
  background:
    linear-gradient(180deg, rgba(255, 250, 225, 0.65), transparent 24%),
    linear-gradient(180deg, var(--paper) 0%, var(--paper-2) 100%);
  border: 3px solid var(--ink);
  box-shadow:
    0 0 0 2px #8a6336,
    inset 0 0 0 2px var(--paper-3),
    0 7px 0 rgba(0, 0, 0, 0.35),
    0 12px 28px rgba(0, 0, 0, 0.28);
  position: relative;
}

.panel::before,
.panel::after {
  content: '';
  position: absolute;
  width: 5px;
  height: 5px;
  background: #8a6336;
  box-shadow: inset 0 0 0 1px #5c3f1f;
  pointer-events: none;
}

.panel::before {
  left: 4px;
  top: 4px;
}

.panel::after {
  right: 4px;
  bottom: 4px;
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 8px 6px 10px;
  background: linear-gradient(180deg, #4a2f18, #2d1b0d);
  border-bottom: 2px solid var(--ink);
  color: var(--paper);
}

.panel-tag {
  font-family: var(--font-pixel);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: var(--gold);
  flex: 1;
}

.panel-count {
  font-family: var(--font-pixel);
  font-size: 6px;
  color: #c9a26b;
}

.tiny-btn {
  width: 22px;
  height: 22px;
  padding: 0;
  font-family: var(--font-pixel);
  font-size: 9px;
  line-height: 1;
  color: #f2dcaa;
  background: #5a3a1e;
  border: 2px solid #1a1008;
  box-shadow: inset 0 1px 0 rgba(255, 220, 160, 0.25);
  cursor: pointer;
}

.tiny-btn:hover {
  background: #6b4725;
}

/* objective */

#objective-panel {
  position: absolute;
  top: 82px;
  left: 14px;
  width: 326px;
  pointer-events: auto;
  z-index: 12;
}

.obj-main {
  padding: 11px 13px 8px;
}

#obj-title {
  margin: 0 0 7px;
  font-family: var(--font-pixel);
  font-size: 9px;
  line-height: 1.7;
  letter-spacing: 0.01em;
  color: var(--ink);
  text-shadow: 1px 1px 0 rgba(255, 255, 255, 0.4);
}

.obj-bar {
  height: 8px;
  background: #8a6336;
  border: 2px solid var(--ink);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2);
  overflow: hidden;
}

#obj-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(180deg, #a7d96c, #5d9a3a);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45);
  transition: width 0.35s ease;
}

.obj-details {
  padding: 0 13px 12px;
}

#objective-panel.collapsed .obj-details {
  display: none;
}

#obj-desc {
  margin: 0 0 8px;
  font-size: 18px;
  line-height: 1.15;
  color: #4a3119;
}

.obj-reward {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 22px;
  align-items: center;
}

.reward-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  background: #3a2513;
  border: 2px solid #8a6336;
  color: var(--cream);
  font-family: var(--font-pixel);
  font-size: 7px;
  box-shadow: inset 0 1px 0 rgba(255, 220, 160, 0.16);
}

.reward-chip img {
  width: 13px;
  height: 13px;
  image-rendering: pixelated;
}

.reward-label {
  font-family: var(--font-pixel);
  font-size: 6px;
  color: #7a5a33;
  letter-spacing: 0.08em;
}

/* selection */

#selection-panel {
  position: absolute;
  top: 82px;
  right: 14px;
  width: 316px;
  padding: 11px;
  pointer-events: auto;
  z-index: 13;
}

.sel-top {
  display: flex;
  align-items: flex-start;
  gap: 9px;
}

#sel-icon {
  width: 46px;
  height: 46px;
  image-rendering: pixelated;
  filter: drop-shadow(0 2px 0 rgba(60, 35, 10, 0.3));
  flex-shrink: 0;
}

.sel-heading {
  flex: 1;
  min-width: 0;
}

#sel-name {
  margin: 1px 0 4px;
  font-family: var(--font-pixel);
  font-size: 9px;
  line-height: 1.5;
  color: var(--ink);
}

#sel-kind {
  font-family: var(--font-pixel);
  font-size: 5.5px;
  letter-spacing: 0.12em;
  color: #7a5a33;
}

#btn-sel-close {
  flex-shrink: 0;
}

.sel-status {
  margin: 9px 0 8px;
  padding: 7px 8px;
  background: rgba(90, 58, 30, 0.12);
  border: 2px solid rgba(90, 58, 30, 0.28);
  font-size: 17px;
  line-height: 1.1;
  color: #4a3119;
  min-height: 38px;
}

.sel-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 8px;
  margin-bottom: 9px;
}

.sel-stat {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 5px;
  background: rgba(255, 250, 225, 0.45);
  border-bottom: 1px solid rgba(90, 58, 30, 0.22);
  font-size: 15px;
  color: #5a3a1e;
}

.sel-stat b {
  font-family: var(--font-pixel);
  font-size: 6.5px;
  color: var(--ink);
  font-weight: normal;
  padding-top: 2px;
  text-align: right;
}

.danger-btn {
  width: 100%;
  padding: 8px 6px;
  font-family: var(--font-pixel);
  font-size: 7px;
  color: #fff1cb;
  background: linear-gradient(180deg, #c9503c, #8f2f25);
  border: 2px solid var(--ink);
  box-shadow:
    inset 0 1px 0 rgba(255, 220, 160, 0.3),
    0 3px 0 #5a1a13;
  cursor: pointer;
}

.danger-btn:hover {
  filter: brightness(1.12);
}

.danger-btn:active {
  transform: translateY(2px);
  box-shadow: inset 0 1px 0 rgba(255, 220, 160, 0.2);
}

/* ------------------------------------------------------------- toasts */

#toasts {
  position: absolute;
  top: 82px;
  left: 50%;
  transform: translateX(-50%);
  width: min(560px, calc(100vw - 40px));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  pointer-events: none;
  z-index: 30;
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: fit-content;
  max-width: 100%;
  padding: 8px 12px;
  background: linear-gradient(180deg, rgba(58, 37, 19, 0.97), rgba(35, 22, 10, 0.97));
  border: 2px solid #8a6336;
  border-left: 5px solid var(--gold);
  box-shadow:
    0 0 0 2px #1a1008,
    0 5px 0 rgba(0, 0, 0, 0.35);
  color: var(--paper);
  font-size: 18px;
  line-height: 1.1;
  text-align: left;
  animation: toast-in 0.2s steps(3, end);
}

.toast.good {
  border-left-color: var(--green);
}

.toast.warn {
  border-left-color: #ff8f5a;
}

.toast.quest {
  border-left-color: #ffe08a;
  background: linear-gradient(180deg, #4a3416, #2b1c09);
}

.toast.leaving {
  opacity: 0;
  transform: translateY(-6px);
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

.toast-icon {
  font-family: var(--font-pixel);
  font-size: 10px;
  color: var(--gold);
  line-height: 1.3;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes chip-pulse {
  0%,
  100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.35);
  }
}

/* ------------------------------------------------------------- bottom */

#bottom-ui {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 0 14px calc(10px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  pointer-events: none;
  z-index: 14;
}

#hint-bar {
  pointer-events: auto;
  min-height: 31px;
  max-width: min(960px, 100%);
  padding: 5px 14px;
  background: linear-gradient(180deg, rgba(35, 22, 10, 0.92), rgba(22, 14, 6, 0.94));
  border: 2px solid #8a6336;
  box-shadow: 0 0 0 2px #120b05;
  color: #f2dcaa;
  font-size: 17px;
  line-height: 1.2;
  text-align: center;
  text-shadow: 1px 1px 0 #000;
}

#hint-bar.warn {
  border-color: #c9503c;
  color: #ffb9a5;
}

#build-bar {
  pointer-events: auto;
  width: 100%;
  max-width: 1010px;
  padding: 8px;
  background:
    linear-gradient(180deg, rgba(255, 220, 160, 0.08), transparent 35%),
    linear-gradient(180deg, #4a2f18, #2b190a);
  border: 3px solid #1a1008;
  box-shadow:
    0 0 0 2px #7a4e24,
    0 8px 0 rgba(0, 0, 0, 0.35),
    0 14px 30px rgba(0, 0, 0, 0.35);
}

#build-list {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 7px;
}

.build-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-height: 92px;
  padding: 8px 4px 6px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.5), transparent 30%),
    linear-gradient(180deg, #f6e3b6, #e2c285);
  border: 2px solid #3a2513;
  box-shadow:
    inset 0 0 0 2px #fff3cf,
    0 3px 0 #120b05;
  cursor: pointer;
  color: var(--ink);
  transition:
    transform 0.08s ease,
    background 0.08s ease;
}

.build-card:hover {
  transform: translateY(-2px);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.65), transparent 30%),
    linear-gradient(180deg, #fbeecb, #ecd39f);
}

.build-card.selected {
  transform: translateY(-3px);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.7), transparent 30%),
    linear-gradient(180deg, #ffe9a3, #f2c14e);
  border-color: var(--ink);
  box-shadow:
    inset 0 0 0 2px #fffbe8,
    0 0 0 2px #f2c14e,
    0 4px 0 #120b05;
}

.build-card.locked {
  filter: saturate(0.45) brightness(0.88);
}

.build-card .key {
  position: absolute;
  top: 3px;
  left: 5px;
  font-family: var(--font-pixel);
  font-size: 5.5px;
  color: #8a6336;
}

.build-card .bicon {
  width: 38px;
  height: 38px;
  image-rendering: pixelated;
  filter: drop-shadow(0 2px 0 rgba(90, 58, 30, 0.25));
  pointer-events: none;
}

.build-card .bname {
  font-family: var(--font-pixel);
  font-size: 6px;
  line-height: 1.55;
  text-align: center;
  letter-spacing: 0.01em;
  pointer-events: none;
}

.build-card .bcost {
  display: flex;
  gap: 5px;
  align-items: center;
  min-height: 14px;
  font-family: var(--font-pixel);
  font-size: 7px;
  pointer-events: none;
}

.bcost .cost {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.bcost img {
  width: 12px;
  height: 12px;
  image-rendering: pixelated;
}

.bcost .lack {
  color: var(--red-dark);
}

.lock-note {
  font-family: var(--font-body);
  font-size: 12px;
  line-height: 1;
  color: #8f2f25;
  text-align: center;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ------------------------------------------------------------- overlays */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

#start-screen {
  z-index: 60;
  flex-direction: column;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(30, 50, 28, 0.35) 0%, rgba(10, 18, 10, 0.82) 62%, rgba(5, 9, 5, 0.96) 100%);
  backdrop-filter: blur(1.5px);
}

#start-screen::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(180deg, transparent 60%, rgba(0, 0, 0, 0.5)),
    radial-gradient(ellipse at 50% 50%, transparent 40%, rgba(0, 0, 0, 0.45));
}

.start-card {
  position: relative;
  z-index: 2;
  text-align: center;
  padding: 18px 28px 26px;
  max-width: 780px;
  animation: title-in 0.5s steps(4, end);
}

@keyframes title-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.start-kicker {
  font-family: var(--font-pixel);
  font-size: 7px;
  letter-spacing: 0.24em;
  color: #c9a26b;
  margin-bottom: 14px;
  text-shadow: 1px 1px 0 #000;
}

.start-logo {
  width: 86px;
  height: 86px;
  image-rendering: pixelated;
  filter: drop-shadow(0 6px 0 rgba(0, 0, 0, 0.45));
  margin-bottom: 10px;
}

.game-title {
  margin: 0;
  font-family: var(--font-pixel);
  font-size: clamp(30px, 6.4vw, 62px);
  line-height: 1.12;
  letter-spacing: 0.02em;
  color: var(--gold);
  -webkit-text-stroke: 2px #241609;
  paint-order: stroke fill;
  text-shadow:
    0 4px 0 #8a5a1e,
    0 8px 0 #2a1a10,
    0 14px 28px rgba(0, 0, 0, 0.6);
}

.tagline {
  margin: 18px 0 24px;
  font-size: 24px;
  letter-spacing: 0.03em;
  color: #f2dcaa;
  text-shadow: 1px 1px 0 #000;
}

.start-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.big-btn {
  font-family: var(--font-pixel);
  font-size: 12px;
  letter-spacing: 0.04em;
  padding: 16px 30px;
  color: #2a1a10;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.55), transparent 35%),
    linear-gradient(180deg, #ffe08a, #e8ad3c);
  border: 3px solid var(--ink);
  box-shadow:
    inset 0 0 0 2px #fff3cf,
    0 6px 0 #7a4e1e,
    0 10px 20px rgba(0, 0, 0, 0.4);
  cursor: pointer;
  text-shadow: 1px 1px 0 rgba(255, 255, 255, 0.35);
}

.big-btn:hover {
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.big-btn:active {
  transform: translateY(4px);
  box-shadow:
    inset 0 0 0 2px #fff3cf,
    0 2px 0 #7a4e1e;
}

.ghost-btn {
  font-family: var(--font-pixel);
  font-size: 8px;
  letter-spacing: 0.04em;
  padding: 14px 18px;
  color: #f2dcaa;
  background: rgba(35, 22, 10, 0.8);
  border: 3px solid #c9a26b;
  box-shadow: 0 5px 0 rgba(0, 0, 0, 0.4);
  cursor: pointer;
}

.ghost-btn:hover {
  background: rgba(74, 47, 24, 0.92);
  color: #fff1cb;
}

.ghost-btn:active {
  transform: translateY(3px);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.4);
}

.link-btn {
  margin-top: 18px;
  padding: 4px 8px;
  font-family: var(--font-body);
  font-size: 19px;
  color: #d8b980;
  background: none;
  border: none;
  border-bottom: 1px dotted #8a6336;
  cursor: pointer;
}

.link-btn:hover {
  color: #fff1cb;
}

.start-controls {
  margin-top: 22px;
  font-family: var(--font-pixel);
  font-size: 6px;
  letter-spacing: 0.08em;
  line-height: 2;
  color: #8f7a55;
  text-shadow: 1px 1px 0 #000;
}

.start-credit {
  position: absolute;
  bottom: calc(14px + var(--safe-bottom));
  left: 0;
  right: 0;
  text-align: center;
  z-index: 2;
  font-size: 15px;
  color: #6f6046;
}

/* win */

#win-screen {
  z-index: 50;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(60, 48, 18, 0.35), rgba(8, 12, 8, 0.92) 70%);
}

.win-card {
  width: min(540px, 94vw);
  padding: 0 22px 22px;
  text-align: center;
  animation: title-in 0.45s steps(4, end);
}

.win-ribbon {
  margin: 0 -10px 18px;
  padding: 11px 10px 9px;
  font-family: var(--font-pixel);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: #2a1a10;
  background: linear-gradient(180deg, #ffe08a, #e0a93c);
  border-bottom: 3px solid var(--ink);
  box-shadow: 0 2px 0 rgba(255, 255, 255, 0.35) inset;
}

.win-title {
  margin: 0 0 10px;
  font-family: var(--font-pixel);
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink);
}

.win-copy {
  margin: 0 0 16px;
  font-size: 20px;
  line-height: 1.15;
  color: #4a3119;
}

.win-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin: 0 0 18px;
  text-align: left;
}

.win-stat {
  padding: 6px 8px;
  background: rgba(90, 58, 30, 0.12);
  border: 2px solid rgba(90, 58, 30, 0.25);
  font-size: 17px;
  color: #5a3a1e;
}

.win-stat b {
  display: block;
  font-family: var(--font-pixel);
  font-size: 6px;
  color: #7a5a33;
  margin-bottom: 4px;
  font-weight: normal;
}

.win-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
}

.win-actions .big-btn {
  font-size: 9px;
  padding: 13px 18px;
}

/* modal */

#modal {
  z-index: 55;
  background: rgba(8, 12, 8, 0.72);
  backdrop-filter: blur(2px);
}

.modal-card {
  width: min(560px, 94vw);
  max-height: 86vh;
  overflow: auto;
  padding: 20px 22px 22px;
}

.modal-close {
  position: absolute;
  top: 9px;
  right: 9px;
  z-index: 2;
}

#modal-title {
  margin: 0 0 14px;
  padding-right: 30px;
  font-family: var(--font-pixel);
  font-size: 13px;
  line-height: 1.5;
  color: var(--ink);
}

#modal-body {
  font-size: 19px;
  line-height: 1.15;
  color: #3a2513;
}

#modal-body p {
  margin: 0 0 10px;
}

.menu-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.menu-list button {
  width: 100%;
  padding: 10px 12px;
  text-align: left;
  font-family: var(--font-pixel);
  font-size: 8px;
  color: var(--ink);
  background: linear-gradient(180deg, #f8e8c0, #e6c88e);
  border: 2px solid #3a2513;
  box-shadow:
    inset 0 0 0 2px #fff3cf,
    0 3px 0 rgba(26, 16, 8, 0.7);
  cursor: pointer;
}

.menu-list button:hover {
  background: linear-gradient(180deg, #fff3cf, #f0d7a2);
}

.menu-list button.danger {
  color: #8f2f25;
}

.menu-list .menu-note {
  padding: 4px 2px 8px;
  font-family: var(--font-body);
  font-size: 16px;
  color: #6b4a2a;
}

.how-grid {
  display: grid;
  grid-template-columns: 26px 1fr;
  gap: 7px 9px;
  margin: 0 0 14px;
  align-items: start;
}

.how-grid img {
  width: 26px;
  height: 26px;
  image-rendering: pixelated;
}

.how-grid b {
  font-family: var(--font-pixel);
  font-size: 7px;
  color: var(--ink);
  font-weight: normal;
  display: block;
  margin: 2px 0 3px;
}

.how-grid span {
  font-size: 17px;
  line-height: 1.1;
  color: #4a3119;
}

.how-section-title {
  margin: 14px 0 7px;
  font-family: var(--font-pixel);
  font-size: 8px;
  color: #7a4e24;
  letter-spacing: 0.06em;
}

.key-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 10px;
}

.key-cap {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 6px;
  font-size: 15px;
  background: rgba(90, 58, 30, 0.1);
  border: 1px solid rgba(90, 58, 30, 0.3);
  color: #4a3119;
}

.key-cap b {
  font-family: var(--font-pixel);
  font-size: 6px;
  color: var(--ink);
  font-weight: normal;
  padding: 2px 4px;
  background: #e0c48e;
  border: 1px solid #8a6336;
}

/* ------------------------------------------------------------- responsive */

@media (max-width: 1120px) {
  .brand-sub {
    display: none;
  }

  .brand-title {
    font-size: 9px;
  }

  .res-chip {
    padding-right: 7px;
  }

  #objective-panel {
    width: 300px;
  }

  #selection-panel {
    width: 288px;
  }
}

@media (max-width: 900px) {
  #topbar {
    gap: 10px;
  }

  .brand-text {
    display: none;
  }

  .brand-logo {
    width: 32px;
    height: 32px;
  }

  .res-chip {
    height: 32px;
    padding: 0 6px;
  }

  .res-chip img {
    width: 17px;
    height: 17px;
  }

  .res-val {
    font-size: 8px;
  }

  .res-cap {
    font-size: 6px;
    margin-bottom: 4px;
  }

  .res-label {
    display: none;
  }

  .speed-btn {
    min-width: 26px;
    height: 27px;
    font-size: 6px;
  }

  .top-btn {
    height: 27px;
    font-size: 6px;
  }

  .build-card {
    min-height: 86px;
  }

  .build-card .bicon {
    width: 32px;
    height: 32px;
  }

  .build-card .bname {
    font-size: 5.5px;
  }

  .build-card .bcost {
    font-size: 6px;
  }
}

@media (max-width: 760px) {
  #topbar {
    min-height: 52px;
    padding: calc(5px + var(--safe-top)) 8px 5px;
    gap: 6px;
  }

  .brand {
    display: none;
  }

  .resources {
    gap: 4px;
  }

  .res-chip {
    height: 30px;
    padding: 0 5px;
    gap: 3px;
    border-width: 2px;
  }

  .res-chip img {
    width: 15px;
    height: 15px;
  }

  .res-val {
    font-size: 7px;
  }

  .res-cap {
    display: none;
  }

  .res-chip.res-idle {
    display: none;
  }

  .top-actions {
    gap: 4px;
  }

  .speed-group {
    gap: 2px;
  }

  .speed-btn {
    min-width: 24px;
    height: 25px;
    font-size: 5.5px;
    padding: 0 3px;
  }

  #btn-sound {
    display: none;
  }

  .top-btn {
    height: 25px;
    padding: 0 5px;
    font-size: 5.5px;
  }

  #objective-panel {
    top: calc(58px + var(--safe-top));
    left: 8px;
    right: 8px;
    width: auto;
  }

  .panel-head {
    padding: 5px 6px 4px 8px;
  }

  .panel-tag {
    font-size: 6px;
  }

  .panel-count {
    font-size: 5.5px;
  }

  .tiny-btn {
    width: 20px;
    height: 20px;
    font-size: 8px;
  }

  .obj-main {
    padding: 7px 9px 6px;
  }

  #obj-title {
    font-size: 7.5px;
    margin-bottom: 5px;
    line-height: 1.6;
  }

  .obj-bar {
    height: 6px;
  }

  .obj-details {
    display: none;
  }

  #objective-panel.expanded .obj-details {
    display: block;
    padding: 0 9px 9px;
  }

  #obj-desc {
    font-size: 16px;
    margin-bottom: 6px;
  }

  .reward-chip {
    font-size: 6px;
    padding: 2px 5px;
  }

  #toasts {
    top: calc(128px + var(--safe-top));
    width: calc(100vw - 24px);
  }

  .toast {
    font-size: 16px;
    padding: 6px 9px;
  }

  #selection-panel {
    top: auto;
    left: 8px;
    right: 8px;
    bottom: calc(122px + var(--safe-bottom));
    width: auto;
    max-height: 44vh;
    overflow: auto;
    padding: 9px;
  }

  #sel-icon {
    width: 38px;
    height: 38px;
  }

  #sel-name {
    font-size: 8px;
  }

  .sel-status {
    font-size: 15px;
    min-height: 30px;
    margin: 6px 0;
    padding: 5px 6px;
  }

  .sel-stat {
    font-size: 14px;
  }

  .sel-stat b {
    font-size: 6px;
  }

  #bottom-ui {
    padding: 0 6px calc(6px + var(--safe-bottom));
    gap: 4px;
  }

  #hint-bar {
    width: 100%;
    font-size: 14px;
    min-height: 24px;
    padding: 3px 8px;
    border-width: 1px;
  }

  #build-bar {
    padding: 5px;
    border-width: 2px;
  }

  #build-list {
    display: flex;
    gap: 5px;
    overflow-x: auto;
    overflow-y: hidden;
    padding-bottom: 2px;
    scrollbar-width: thin;
    scrollbar-color: #8a6336 #2b190a;
    -webkit-overflow-scrolling: touch;
  }

  .build-card {
    flex: 0 0 68px;
    min-height: 76px;
    padding: 7px 2px 4px;
  }

  .build-card .bicon {
    width: 28px;
    height: 28px;
  }

  .build-card .bname {
    font-size: 5px;
    line-height: 1.5;
  }

  .build-card .bcost {
    gap: 3px;
    font-size: 6px;
  }

  .bcost img {
    width: 10px;
    height: 10px;
  }

  .lock-note {
    font-size: 10px;
  }

  .overlay {
    padding: 12px;
  }

  .start-card {
    padding: 8px 10px 18px;
  }

  .start-logo {
    width: 64px;
    height: 64px;
    margin-bottom: 8px;
  }

  .start-kicker {
    font-size: 5.5px;
    margin-bottom: 10px;
  }

  .tagline {
    font-size: 20px;
    margin: 12px 0 18px;
  }

  .start-actions {
    flex-direction: column;
    gap: 9px;
  }

  .big-btn {
    font-size: 10px;
    padding: 14px 22px;
    width: min(280px, 82vw);
  }

  .ghost-btn {
    font-size: 7px;
    padding: 11px 14px;
    width: min(280px, 82vw);
  }

  .link-btn {
    font-size: 17px;
    margin-top: 12px;
  }

  .start-controls {
    font-size: 5px;
    margin-top: 14px;
    line-height: 1.8;
  }

  .start-credit {
    font-size: 13px;
  }

  .win-card {
    padding: 0 14px 16px;
  }

  .win-title {
    font-size: 12px;
  }

  .win-copy {
    font-size: 18px;
  }

  .win-ribbon {
    font-size: 7px;
  }

  .win-stat {
    font-size: 15px;
  }

  .modal-card {
    padding: 16px 14px 16px;
  }

  #modal-title {
    font-size: 10px;
  }

  #modal-body {
    font-size: 17px;
  }

  .menu-list button {
    font-size: 7px;
    padding: 9px 10px;
  }

  .how-grid {
    grid-template-columns: 22px 1fr;
    gap: 6px 7px;
  }

  .how-grid img {
    width: 22px;
    height: 22px;
  }

  .how-grid b {
    font-size: 6px;
  }

  .how-grid span {
    font-size: 15px;
  }

  .how-section-title {
    font-size: 7px;
  }
}

@media (max-width: 430px) {
  .res-chip {
    padding: 0 4px;
  }

  .res-chip img {
    width: 13px;
    height: 13px;
  }

  .res-val {
    font-size: 6.5px;
  }

  .speed-btn {
    min-width: 22px;
    font-size: 5px;
  }

  .top-btn {
    font-size: 5px;
  }

  #toasts {
    top: calc(124px + var(--safe-top));
  }
}

@media (prefers-reduced-motion: reduce) {
  .toast,
  .start-card,
  .win-card {
    animation: none;
  }
}

